using Microsoft.EntityFrameworkCore;
using XiangqiOnline.Domain.Entities;
using XiangqiOnline.Domain.Enums;

namespace XiangqiOnline.Infrastructure.Persistence;

public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<User> Users => Set<User>();
    public DbSet<RefreshToken> RefreshTokens => Set<RefreshToken>();
    public DbSet<Room> Rooms => Set<Room>();
    public DbSet<RoomMember> RoomMembers => Set<RoomMember>();
    public DbSet<Game> Games => Set<Game>();
    public DbSet<GameMove> GameMoves => Set<GameMove>();
    public DbSet<GameSnapshot> GameSnapshots => Set<GameSnapshot>();
    public DbSet<Invitation> Invitations => Set<Invitation>();
    public DbSet<Message> Messages => Set<Message>();
    public DbSet<GameEvent> GameEvents => Set<GameEvent>();
    public DbSet<ChatMessage> ChatMessages => Set<ChatMessage>();
    public DbSet<CallSession> CallSessions => Set<CallSession>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<User>(e => { e.ToTable("Users"); e.HasKey(x => x.Id); e.Property(x => x.Username).HasMaxLength(64).IsRequired(); e.Property(x => x.NormalizedUsername).HasMaxLength(64).IsRequired(); e.Property(x => x.Email).HasMaxLength(254).IsRequired(); e.Property(x => x.NormalizedEmail).HasMaxLength(254).IsRequired(); e.Property(x => x.PasswordHash).HasMaxLength(512).IsRequired(); e.Property(x => x.DisplayName).HasMaxLength(80).IsRequired(); e.Property(x => x.AvatarUrl).HasMaxLength(2048); e.HasIndex(x => x.NormalizedUsername).IsUnique(); e.HasIndex(x => x.NormalizedEmail).IsUnique(); });
        model.Entity<RefreshToken>(e => { e.ToTable("RefreshTokens"); e.HasKey(x => x.Id); e.Property(x => x.TokenHash).HasMaxLength(128).IsRequired(); e.HasIndex(x => x.TokenHash).IsUnique(); e.HasIndex(x => x.UserId); e.HasOne<User>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); e.HasOne<RefreshToken>().WithMany().HasForeignKey(x => x.ReplacedByTokenId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<Room>(e => { e.ToTable("Rooms", t => t.HasCheckConstraint("CK_Rooms_MaxPlayers", "[MaxPlayers] = 2")); e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(12).IsRequired(); e.Property(x => x.Name).HasMaxLength(80).IsRequired(); e.Property(x => x.Version).IsConcurrencyToken(); e.HasIndex(x => x.Code).IsUnique(); e.HasIndex(x => x.OwnerId); e.HasOne<User>().WithMany().HasForeignKey(x => x.OwnerId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<RoomMember>(e => { e.ToTable("RoomMembers", t => { t.HasCheckConstraint("CK_RoomMembers_Side", "[Side] IS NULL OR [Side] IN (0, 1)"); t.HasCheckConstraint("CK_RoomMembers_Role", "[Role] IN (0, 1, 2)"); }); e.HasKey(x => x.Id); e.HasIndex(x => new { x.RoomId, x.UserId }).IsUnique().HasFilter("[LeftAt] IS NULL"); e.HasIndex(x => new { x.RoomId, x.Side }).IsUnique().HasFilter("[LeftAt] IS NULL AND [Side] IS NOT NULL AND [Role] IN (0, 1)"); e.HasIndex(x => x.UserId); e.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<Game>(e => { e.ToTable("Games"); e.HasKey(x => x.Id); e.Property(x => x.CurrentFen).HasMaxLength(256).IsRequired(); e.Property(x => x.AiLastError).HasMaxLength(300); e.Property(x => x.AiTurnStatus).HasDefaultValue(AiTurnStatus.None); e.Property(x => x.AiRetryCount).HasDefaultValue(0); e.Property(x => x.AiCompletedDepth).HasDefaultValue(0); e.Property(x => x.AiElapsedMs).HasDefaultValue(0L); e.Property(x => x.AiNodesSearched).HasDefaultValue(0L); e.Property(x => x.Version).IsConcurrencyToken(); e.Property(x => x.TimeControlInitialMs).HasDefaultValue(600_000L); e.Property(x => x.RedRemainingMs).HasDefaultValue(600_000L); e.Property(x => x.BlackRemainingMs).HasDefaultValue(600_000L); e.Property(x => x.TimeControlIncrementMs).HasDefaultValue(0L); e.HasIndex(x => x.RoomId); e.HasIndex(x => x.RedPlayerId); e.HasIndex(x => x.BlackPlayerId); e.HasIndex(x => new { x.Mode, x.Status, x.TurnStartedAtUtc }); e.HasIndex(x => new { x.Mode, x.AiTurnStatus, x.AiTurnLeaseUntilUtc }); e.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.RedPlayerId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.BlackPlayerId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.HumanPlayerId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.WinnerId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<GameMove>(e => { e.ToTable("GameMoves"); e.HasKey(x => x.Id); e.Property(x => x.FromSquare).HasMaxLength(2).IsRequired(); e.Property(x => x.ToSquare).HasMaxLength(2).IsRequired(); e.Property(x => x.Piece).HasMaxLength(16).IsRequired(); e.Property(x => x.CapturedPiece).HasMaxLength(16); e.Property(x => x.FenBefore).HasMaxLength(256); e.Property(x => x.FenAfter).HasMaxLength(256).IsRequired(); e.Property(x => x.IsAiMove).HasDefaultValue(false); e.HasIndex(x => new { x.GameId, x.Ply }).IsUnique(); e.HasIndex(x => new { x.GameId, x.ClientMoveId }).IsUnique(); e.HasIndex(x => x.GameId); e.HasOne<Game>().WithMany().HasForeignKey(x => x.GameId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.PlayerId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<GameSnapshot>(e => { e.ToTable("GameSnapshots"); e.HasKey(x => x.Id); e.Property(x => x.Fen).HasMaxLength(256).IsRequired(); e.Property(x => x.Metadata).HasColumnType("nvarchar(max)").IsRequired(); e.Property(x => x.RedRemainingMs).HasDefaultValue(600_000L); e.Property(x => x.BlackRemainingMs).HasDefaultValue(600_000L); e.Property(x => x.CurrentTurn).HasDefaultValue(Side.Red); e.Property(x => x.Version).HasDefaultValue(0L); e.HasIndex(x => new { x.GameId, x.Ply }).IsUnique(); e.HasOne<Game>().WithMany().HasForeignKey(x => x.GameId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<Invitation>(e => { e.ToTable("Invitations"); e.HasKey(x => x.Id); e.Property(x => x.TokenHash).HasMaxLength(128); e.HasIndex(x => x.TokenHash).IsUnique().HasFilter("[TokenHash] IS NOT NULL"); e.HasIndex(x => new { x.RoomId, x.InviteeId }).IsUnique().HasFilter("[InviteeId] IS NOT NULL AND [Status] = 0"); e.HasIndex(x => new { x.InviteeId, x.Status, x.ExpiresAt }); e.HasIndex(x => x.RoomId); e.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.InviterId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.InviteeId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<Message>(e => { e.ToTable("Messages"); e.HasKey(x => x.Id); e.Property(x => x.Content).HasMaxLength(2000).IsRequired(); e.HasIndex(x => new { x.RoomId, x.CreatedAt }); e.HasIndex(x => x.SenderId); e.HasOne<Room>().WithMany().HasForeignKey(x => x.RoomId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.SenderId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<GameEvent>(e => { e.ToTable("GameEvents"); e.HasKey(x => x.Id); e.Property(x => x.Payload).HasColumnType("nvarchar(max)").IsRequired(); e.HasIndex(x => new { x.GameId, x.CreatedAt }); e.HasOne<Game>().WithMany().HasForeignKey(x => x.GameId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<ChatMessage>(e => { e.ToTable("ChatMessages"); e.HasKey(x => x.Id); e.Property(x => x.Content).HasMaxLength(1000).IsRequired(); e.HasIndex(x => new { x.GameId, x.SenderUserId, x.ClientMessageId }).IsUnique(); e.HasIndex(x => new { x.GameId, x.CreatedAtUtc, x.Id }); e.HasOne<Game>().WithMany().HasForeignKey(x => x.GameId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.SenderUserId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<CallSession>(e => { e.ToTable("CallSessions"); e.HasKey(x => x.Id); e.Property(x => x.EndReason).HasMaxLength(64); e.Property(x => x.Version).IsConcurrencyToken(); e.HasIndex(x => x.GameId).HasFilter("[Status] IN (0, 1, 2, 3)").IsUnique(); e.HasIndex(x => new { x.Status, x.ExpiresAtUtc }); e.HasOne<Game>().WithMany().HasForeignKey(x => x.GameId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.CallerUserId).OnDelete(DeleteBehavior.Restrict); e.HasOne<User>().WithMany().HasForeignKey(x => x.CalleeUserId).OnDelete(DeleteBehavior.Restrict); });
    }
}
